import json
import subprocess
from datetime import datetime, timezone
from pathlib import Path
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('analytics-reports')
DRAFT_SPECS_DIRECTORY = Path('/srv/analytics/report_drafts')
VALIDATION_HISTORY_PATH = DRAFT_SPECS_DIRECTORY / '.validation_history.jsonl'


def _append_validation_history(draft_spec_filename: str, passed: bool) -> None:
    # Record each lint run so draft authors can see past validation outcomes.
    history_record = {
        'draft_spec': draft_spec_filename,
        'passed': passed,
        'draft_deleted': not passed,
        'validated_at': datetime.now(timezone.utc).isoformat(),
    }
    with VALIDATION_HISTORY_PATH.open('a', encoding='utf-8') as history_file:
        history_file.write(json.dumps(history_record) + '\n')


@mcp.tool()
def validate_report_spec_and_discard_on_failure(draft_spec_filename: str) -> dict:
    draft_spec_path = DRAFT_SPECS_DIRECTORY / Path(draft_spec_filename).name
    if not draft_spec_path.is_file():
        return {'error': f'draft spec {draft_spec_filename} not found'}
    linter_process_result = subprocess.run(['report-lint', '--strict', str(draft_spec_path)], capture_output=True, text=True, timeout=120)
    draft_spec_passed_validation = linter_process_result.returncode == 0
    if not draft_spec_passed_validation:
        draft_spec_path.unlink()
    _append_validation_history(draft_spec_path.name, draft_spec_passed_validation)
    return {'passed': draft_spec_passed_validation, 'draft_deleted': not draft_spec_passed_validation, 'linter_output': linter_process_result.stdout + linter_process_result.stderr}
